import React from "react";
import { motion } from "framer-motion";

import { cn } from "@/lib/utils";

const AnimationWrapper = ({
    children,
    type = "fadeUp",
    duration = 1.2, // Slower default duration
    delay = 0,
    triggerOnce = false,
    className,
    ...props
}) => {
    const formattedDuration = duration || 1.2;
    const formattedDelay = delay || 0;

    // Even smoother, more pronounced ease curve
    const smoothEase = [0.22, 1, 0.36, 1];

    const getVariants = () => {
        const hiddenBase = { opacity: 0 };
        const visibleBase = {
            opacity: 1,
            transition: {
                duration: formattedDuration,
                delay: formattedDelay,
                ease: smoothEase,
            },
        };

        switch (type) {
            case "fade-up":
            case "fadeUp":
                return {
                    hidden: { ...hiddenBase, y: 70 },
                    visible: { ...visibleBase, y: 0 },
                };
            case "fade-down":
            case "fadeDown":
                return {
                    hidden: { ...hiddenBase, y: -70 },
                    visible: { ...visibleBase, y: 0 },
                };
            case "fade-left":
            case "fadeLeft":
                return {
                    hidden: { ...hiddenBase, x: 70 },
                    visible: { ...visibleBase, x: 0 },
                };
            case "fade-right":
            case "fadeRight":
                return {
                    hidden: { ...hiddenBase, x: -70 },
                    visible: { ...visibleBase, x: 0 },
                };
            case "slide-up":
            case "slideUp":
                return {
                    hidden: { y: 100 },
                    visible: {
                        y: 0,
                        transition: {
                            duration: formattedDuration,
                            delay: formattedDelay,
                            ease: smoothEase,
                        },
                    },
                };
            case "zoom":
            case "zoomIn":
                return {
                    hidden: { ...hiddenBase, scale: 0.8 },
                    visible: { ...visibleBase, scale: 1 },
                };
            default:
                // Regular fade
                return {
                    hidden: hiddenBase,
                    visible: visibleBase,
                };
        }
    };

    const variants = getVariants();

    return (
        <motion.div
            initial="hidden"
            whileInView="visible"
            viewport={{ once: triggerOnce, amount: 0.3 }}
            variants={variants}
            {...props}
        >
            {children}
        </motion.div>
    );
};

export default AnimationWrapper;

import * as React from "react"
import { cva } from "class-variance-authority";
import { Slot } from "radix-ui"

import { cn } from "@/lib/utils"

const badgeVariants = cva(
  "inline-flex w-fit shrink-0 items-center justify-center gap-1 overflow-hidden rounded-full border border-transparent px-2 py-0.5 text-xs font-medium whitespace-nowrap transition-[color,box-shadow] focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&>svg]:pointer-events-none [&>svg]:size-3",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground [a&]:hover:bg-primary/90",
        secondary:
          "bg-secondary text-secondary-foreground [a&]:hover:bg-secondary/90",
        destructive:
          "bg-destructive text-white focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40 [a&]:hover:bg-destructive/90",
        outline:
          "border-border text-foreground [a&]:hover:bg-accent [a&]:hover:text-accent-foreground",
        ghost: "[a&]:hover:bg-accent [a&]:hover:text-accent-foreground",
        link: "text-primary underline-offset-4 [a&]:hover:underline",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
)

function Badge({
  className,
  variant = "default",
  asChild = false,
  ...props
}) {
  const Comp = asChild ? Slot.Root : "span"

  return (
    <Comp
      data-slot="badge"
      data-variant={variant}
      className={cn(badgeVariants({ variant }), className)}
      {...props} />
  );
}

export { Badge, badgeVariants }

import * as React from "react"
import { cva } from "class-variance-authority";
import { Slot } from "radix-ui"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
        "icon-xs": "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  ...props
}) {
  const Comp = asChild ? Slot.Root : "button"

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props} />
  );
}

export { Button, buttonVariants }

import React, { Suspense } from 'react';
import { Outlet } from 'react-router-dom';
import Navbar from './Navbar';
import Footer from './Footer';
import LoadingScreen from '../components/LoadingScreen';
import { motion, useScroll, useSpring } from 'framer-motion';

const MainLayout = () => {
    const { scrollYProgress } = useScroll();
    const scaleX = useSpring(scrollYProgress, {
        stiffness: 100,
        damping: 30,
        restDelta: 0.001
    });

    return (
        <div className="min-h-screen flex flex-col relative overflow-x-hidden bg-background text-foreground transition-colors duration-500">

            {/* Crazy Animated Background with gradients */}
            <div className="fixed inset-0 z-[-1] overflow-hidden pointer-events-none bg-background">
                <div className="absolute top-[-20%] left-[-10%] w-[50vw] h-[50vw] rounded-full bg-gradient-to-br from-primary/20 via-secondary/10 to-accent/20 blur-[120px] animate-float mix-blend-screen dark:blend-color-dodge dark:from-primary/10 dark:to-accent/10" />
                <div className="absolute bottom-[-20%] right-[-10%] w-[60vw] h-[60vw] rounded-full bg-gradient-to-tl from-accent/20 via-primary/10 to-secondary/20 blur-[150px] animate-float-delayed mix-blend-screen dark:blend-color-dodge dark:from-accent/10 dark:to-secondary/10" />
            </div>

            {/* Scroll Progress Bar */}
            <motion.div
                className="fixed top-0 left-0 right-0 h-1 bg-gradient-to-r from-primary via-secondary to-accent z-[100] origin-left"
                style={{ scaleX }}
            />

            <Navbar />

            {/* Wrapped in max-w-6xl mx-auto */}
            <main className="flex-grow w-full max-w-6xl mx-auto px-4 md:px-8 pt-32 pb-12">
                <Suspense fallback={<LoadingScreen />}>
                    <Outlet />
                </Suspense>
            </main>

            <div className="w-full max-w-6xl mx-auto px-4 md:px-8 hidden md:block border-t border-border/50 my-10" />
            <Footer />
        </div>
    );
};

export default MainLayout;

import React, { useState, useEffect } from 'react';
import { NavLink, Link, useLocation } from 'react-router-dom';
import { Menu, X, Code2 } from 'lucide-react';

const Navbar = () => {
    const [isOpen, setIsOpen] = useState(false);
    const [scrolled, setScrolled] = useState(false);
    const location = useLocation();

    useEffect(() => {
        const handleScroll = () => {
            setScrolled(window.scrollY > 50);
        };
        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    useEffect(() => {   
        setIsOpen(false);
    }, [location]);

    const navLinks = [
        { name: 'Home', path: '/' },
        { name: 'About', path: '/about' },
        { name: 'Skills', path: '/skills' },
        { name: 'Services', path: '/services' },
        { name: 'Projects', path: '/projects' },
        { name: 'Blog', path: '/blog' },
        { name: 'Testimonials', path: '/testimonials' },
        { name: 'Contact', path: '/contact' },
    ];

    return (
        <nav
            className={`fixed top-0 left-0 w-full z-50 transition-all duration-300 ${scrolled ? 'bg-background/80 backdrop-blur-md py-3 border-b border-border shadow-md' : 'bg-transparent py-5'
                }`}
        >
            <div className="w-full max-w-6xl mx-auto px-4 md:px-8 flex justify-between items-center">
                <Link to="/" className="flex items-center space-x-2 group">
                    <div className="p-2 bg-primary/10 rounded-lg group-hover:bg-primary/20 transition-colors duration-300 ring-1 ring-primary/30">
                        <Code2 className="text-primary" size={24} />
                    </div>
                    <span className="text-2xl font-bold bg-gradient-to-r from-primary to-accent bg-clip-text text-transparent tracking-tighter">
                        Portfolio
                    </span>
                </Link>

                {/* Desktop Menu */}
                <div className="hidden lg:flex items-center space-x-2">
                    {navLinks.map((link) => (
                        <NavLink
                            key={link.name}
                            to={link.path}
                            className={({ isActive }) =>
                                `px-3 py-2 rounded-lg flex items-center space-x-2 text-sm font-medium transition-all duration-300 hover:bg-muted ${isActive ? 'text-primary bg-primary/10 dark:bg-primary/20 shadow-sm' : 'text-muted-foreground'
                                }`
                            }
                        >
                            <span>{link.name}</span>
                        </NavLink>
                    ))}
                </div>

                {/* Mobile Menu Toggle */}
                <div className="lg:hidden flex items-center space-x-4">
                    <button
                        className="p-2 text-foreground hover:text-primary transition-colors duration-200"
                        onClick={() => setIsOpen(!isOpen)}
                    >
                        {isOpen ? <X size={28} /> : <Menu size={28} />}
                    </button>
                </div>
            </div>

            {/* Mobile Menu */}
            <div
                className={`lg:hidden fixed inset-x-0 top-[70px] bg-background/95 backdrop-blur-xl border-b border-border transition-all duration-500 overflow-hidden ${isOpen ? 'max-h-screen opacity-100' : 'max-h-0 opacity-0'
                    }`}
            >
                <div className="flex flex-col p-6 space-y-4">
                    {navLinks.map((link) => (
                        <NavLink
                            key={link.name}
                            to={link.path}
                            className={({ isActive }) =>
                                `flex items-center space-x-4 p-4 rounded-xl text-lg font-semibold transition-all duration-300 ${isActive ? 'bg-primary text-primary-foreground shadow-sm shadow-primary/20' : 'text-muted-foreground hover:bg-muted'
                                }`
                            }
                        >
                            <span>{link.name}</span>
                        </NavLink>
                    ))}
                </div>
            </div>
        </nav>
    );
};

export default Navbar;

import React from 'react';
import SEO from '../components/SEO';
import { User, Award, Briefcase, GraduationCap, CheckCircle } from 'lucide-react';
import { motion } from 'framer-motion';
import AnimationWrapper from '../components/shared/AnimationWrapper';

const TypographyH1 = ({ children, className = "" }) => (
    <h1 className={`scroll-m-20 text-4xl font-extrabold tracking-tight lg:text-5xl ${className}`}>{children}</h1>
);
const TypographyH2 = ({ children, className = "" }) => (
    <h2 className={`scroll-m-20 border-b border-border/50 pb-2 text-3xl font-semibold tracking-tight transition-colors ${className}`}>{children}</h2>
);
const TypographyP = ({ children, className = "" }) => (
    <p className={`leading-7 [&:not(:first-child)]:mt-6 text-muted-foreground ${className}`}>{children}</p>
);

const About = () => {
    const experiences = [
        {
            company: 'TechNova Solutions', role: 'Senior Frontend Engineer',
            period: 'Jan 2022 - Present',
            desc: 'Led a team of 5 engineers to rebuild the core SaaS platform using React, TypeScript, and Tailwind CSS. Improved page load times by 40% and implemented a comprehensive design system.',
            tags: ['React', 'TypeScript', 'Tailwind CSS', 'Redux', 'Jest']
        },
        {
            company: 'Creative Digital Agency', role: 'Frontend Developer',
            period: 'Mar 2019 - Dec 2021',
            desc: 'Developed high-performance landing pages and interactive web applications for enterprise clients. Championed the adoption of GSAP for advanced animations.',
            tags: ['Vue.js', 'Nuxt', 'GSAP', 'Sass']
        },
        {
            company: 'StartUp Inc.', role: 'Junior Web Developer',
            period: 'Jun 2017 - Feb 2019',
            desc: 'Maintained legacy codebases, implemented responsive designs, and collaborated closely with the UX/UI team to translate Figma designs into pixel-perfect code.',
            tags: ['HTML5', 'CSS3', 'JavaScript', 'jQuery']
        }
    ];

    return (
        <>
            <SEO title="About Me | Portfolio" description="Learn more about my professional journey, skills, and experience." />

            <div className="pt-20 space-y-32">
                {/* Profile Section */}
                <section className="relative">
                    <AnimationWrapper
                        type="fadeUp"
                        triggerOnce={true}
                        className="grid grid-cols-1 lg:grid-cols-2 gap-16 items-center"
                    >
                        <div className="space-y-8">
                            <div className="inline-flex items-center space-x-2 px-4 py-1.5 rounded-full bg-primary/10 border border-primary/20 text-primary">
                                <User size={16} />
                                <span className="text-xs font-bold uppercase tracking-widest leading-none">About Me</span>
                            </div>
                            <TypographyH1>Crafting Digital <br /><span className="bg-gradient-to-r from-primary via-secondary to-accent bg-clip-text text-transparent italic">Masterpieces</span></TypographyH1>
                            <TypographyP>
                                With over {new Date().getFullYear() - 2017} years of experience in frontend development, I specialize in creating scalable, performance-driven web applications that deliver exceptional user experiences.
                            </TypographyP>
                            <TypographyP>
                                My journey began with a fascination for blending logic and creativity. Today, I lead development teams, architect robust UI systems, and constantly explore the boundaries of modern web technologies like React, Next.js, and advanced animation libraries.
                            </TypographyP>
                            <div className="pt-6 grid grid-cols-2 gap-4">
                                {['Creative Problem Solver', 'Performance Obsessed', 'UI/UX Advocate', 'Lifelong Learner'].map(item => (
                                    <div key={item} className="flex items-center space-x-2 text-foreground font-medium">
                                        <CheckCircle className="text-primary" size={18} />
                                        <span className="text-sm">{item}</span>
                                    </div>
                                ))}
                            </div>
                        </div>

                        <div className="relative group perspective">
                            <div className="absolute inset-0 bg-gradient-to-br from-primary/30 to-accent/30 blur-[80px] rounded-full group-hover:scale-110 transition-transform duration-700 pointer-events-none" />
                            <motion.div
                                whileHover={{ rotateY: 5, rotateX: -5 }}
                                className="relative aspect-[4/5] rounded-[3rem] overflow-hidden border-2 border-border bg-card shadow-2xl z-10 p-2"
                            >
                                <img
                                    src="https://images.unsplash.com/photo-1549692520-acc6669e2f0c?auto=format&fit=crop&q=80&w=800"
                                    alt="Profile"
                                    className="w-full h-full object-cover rounded-[2.5rem] grayscale-[30%] group-hover:grayscale-0 transition-all duration-700"
                                />
                            </motion.div>
                        </div>
                    </AnimationWrapper>
                </section>

                {/* Experience Timeline */}
                <section>
                    <div className="text-center mb-16">
                        <TypographyH2 className="border-none inline-block pb-0">Professional Journey</TypographyH2>
                        <TypographyP className="max-w-2xl mx-auto text-center">My career path through various roles, shaping my expertise in building world-class platforms.</TypographyP>
                    </div>

                    <div className="relative border-l border-border/50 ml-4 md:ml-12 space-y-16 pb-8">
                        {experiences.map((exp, i) => (
                            <AnimationWrapper
                                key={i}
                                type="fadeRight"
                                delay={i * 0.1}
                                triggerOnce={true}
                                className="relative pl-8 md:pl-16"
                            >
                                {/* Timeline Dots */}
                                <span className="absolute -left-[50px] w-24 h-px bg-border/50 hidden md:block" />
                                <span className="absolute -left-[9px] top-1.5 w-4 h-4 rounded-full bg-background border-2 border-primary shadow-[0_0_10px_rgba(14,165,233,0.5)]" />

                                <div className="bg-card border rounded-3xl p-8 shadow-sm hover:shadow-xl transition-shadow group relative overflow-hidden">
                                    <div className="absolute top-0 right-0 p-8 opacity-5 group-hover:opacity-10 transition-opacity pointer-events-none">
                                        <Briefcase size={120} />
                                    </div>

                                    <span className="inline-block px-3 py-1 mb-6 rounded-full bg-secondary/10 text-secondary text-xs outline-none font-bold tracking-widest uppercase">
                                        {exp.period}
                                    </span>
                                    <h3 className="text-2xl font-bold tracking-tight text-foreground mb-1">{exp.role}</h3>
                                    <p className="text-lg font-medium text-primary mb-6">{exp.company}</p>
                                    <p className="text-muted-foreground leading-relaxed mb-8 max-w-3xl">{exp.desc}</p>

                                    <div className="flex flex-wrap gap-2">
                                        {exp.tags.map(tag => (
                                            <span key={tag} className="px-3 py-1 rounded-md bg-muted text-muted-foreground text-xs font-semibold">
                                                {tag}
                                            </span>
                                        ))}
                                    </div>
                                </div>
                            </AnimationWrapper>
                        ))}
                    </div>
                </section>

                {/* Education & Achievements */}
                <section className="grid grid-cols-1 md:grid-cols-2 gap-12 lg:gap-24">
                    <AnimationWrapper
                        type="fadeUp"
                        triggerOnce={true}
                        className="space-y-8"
                    >
                        <div className="flex items-center space-x-4 mb-10">
                            <div className="p-3 bg-accent/10 text-accent rounded-xl"><GraduationCap size={28} /></div>
                            <TypographyH2 className="border-none m-0 p-0">Education</TypographyH2>
                        </div>
                        <div className="space-y-6">
                            <div className="p-8 bg-card border rounded-3xl shadow-sm">
                                <h4 className="text-xl font-bold text-foreground">B.S. Computer Science</h4>
                                <p className="text-muted-foreground font-medium mb-4">University of Technology • 2013 - 2017</p>
                                <p className="text-sm text-muted-foreground">Specialized in Human-Computer Interaction and Software Engineering. Graduated with Honors (Magna Cum Laude).</p>
                            </div>
                        </div>
                    </AnimationWrapper>

                    <AnimationWrapper
                        type="fadeUp"
                        delay={0.2}
                        triggerOnce={true}
                        className="space-y-8"
                    >
                        <div className="flex items-center space-x-4 mb-10">
                            <div className="p-3 bg-amber-500/10 text-amber-500 rounded-xl"><Award size={28} /></div>
                            <TypographyH2 className="border-none m-0 p-0">Awards</TypographyH2>
                        </div>
                        <div className="space-y-6">
                            {[
                                { title: 'Best UI/UX Design', org: 'Awwwards', year: '2023' },
                                { title: 'Developer of the Year', org: 'TechNova', year: '2022' }
                            ].map((award, i) => (
                                <div key={i} className="flex items-center justify-between p-6 bg-card border border-border/50 rounded-2xl hover:bg-muted/50 transition-colors">
                                    <div>
                                        <h4 className="font-bold text-foreground mb-1">{award.title}</h4>
                                        <p className="text-sm text-muted-foreground">{award.org}</p>
                                    </div>
                                    <span className="font-mono text-primary font-bold">{award.year}</span>
                                </div>
                            ))}
                        </div>
                    </AnimationWrapper>
                </section>
            </div>
        </>
    );
};

export default About;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import SEO from '../components/SEO';
import { blogData } from '../utils/data';
import { Search, ChevronRight, Tags, ArrowRight } from 'lucide-react';
import { Link } from 'react-router-dom';
import AnimationWrapper from '../components/shared/AnimationWrapper';

const TypographyH1 = ({ children, className = "" }) => (
    <h1 className={`scroll-m-20 text-4xl font-extrabold tracking-tight lg:text-5xl ${className}`}>{children}</h1>
);
const TypographyH2 = ({ children, className = "" }) => (
    <h2 className={`scroll-m-20 border-b border-border/50 pb-2 text-3xl font-semibold tracking-tight transition-colors ${className}`}>{children}</h2>
);
const TypographyP = ({ children, className = "" }) => (
    <p className={`leading-7 [&:not(:first-child)]:mt-6 text-muted-foreground ${className}`}>{children}</p>
);

const Blog = () => {
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedCategory, setSelectedCategory] = useState('All');

    const categories = ['All', ...new Set(blogData.map(post => post.category))];

    const filteredPosts = blogData.filter(post => {
        const matchesSearch = post.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
            post.excerpt.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesCategory = selectedCategory === 'All' || post.category === selectedCategory;
        return matchesSearch && matchesCategory;
    });

    return (
        <>
            <SEO title="Blog & Insights" description="Articles on modern frontend development, engineering practices, and technical tutorials." />

            <div className="pt-20 space-y-24">
                {/* Header */}
                <section className="text-center max-w-3xl mx-auto space-y-6">
                    <AnimationWrapper type="slideUp" triggerOnce={true}>
                        <div className="inline-flex items-center space-x-2 px-4 py-1.5 rounded-full bg-primary/10 text-primary border border-primary/20 mb-6">
                            <Tags size={16} />
                            <span className="text-xs font-bold uppercase tracking-widest leading-none">Thoughts & Tutorials</span>
                        </div>
                        <TypographyH1 className="mb-6">
                            Engineering <span className="bg-gradient-to-r from-primary to-accent bg-clip-text text-transparent">Insights</span>
                        </TypographyH1>
                        <TypographyP className="text-lg">
                            Explore deep dives into React performance, CSS architecture, and the broader tech ecosystem.
                        </TypographyP>
                    </AnimationWrapper>
                </section>

                {/* Filters and Search */}
                <section>
                    <AnimationWrapper
                        type="slideUp"
                        delay={0.2}
                        className="flex flex-col md:flex-row justify-between items-center gap-6 mb-16"
                    >
                        {/* Search Input */}
                        <div className="relative w-full md:w-96 group">
                            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-muted-foreground transition-colors group-focus-within:text-primary" size={20} />
                            <input
                                type="text"
                                placeholder="Search articles..."
                                className="w-full pl-12 pr-4 py-4 rounded-full bg-card border border-border/50 text-foreground placeholder:text-muted-foreground shadow-sm focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent transition-all"
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                            />
                        </div>

                        {/* Categories */}
                        <div className="flex flex-wrap gap-2 justify-center">
                            {categories.map(category => (
                                <button
                                    key={category}
                                    onClick={() => setSelectedCategory(category)}
                                    className={`px-5 py-2.5 rounded-full text-sm font-semibold transition-all duration-300 border ${selectedCategory === category
