import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import SEO from '../components/SEO';
import { blogData } from '../utils/data';
import { ArrowLeft, Clock, Calendar, Share2, Bookmark, BookmarkCheck, Heart, Printer } from 'lucide-react';
import { motion, useScroll, useSpring } from 'framer-motion';
import AnimationWrapper from '../components/shared/AnimationWrapper';

const TypographyH1 = ({ children, className = "" }) => (
    <h1 className={`scroll-m-20 text-4xl font-extrabold tracking-tight lg:text-5xl ${className}`}>{children}</h1>
);
const TypographyP = ({ children, className = "" }) => (
    <p className={`leading-7 [&:not(:first-child)]:mt-6 text-muted-foreground ${className}`}>{children}</p>
);

const BlogDetails = () => {
    const { slug } = useParams();
    const navigate = useNavigate();
    const [post, setPost] = useState(null);
    const [isSaved, setIsSaved] = useState(false);
    const [likes, setLikes] = useState(124);

    const { scrollYProgress } = useScroll();
    const scaleX = useSpring(scrollYProgress, { stiffness: 100, damping: 30, restDelta: 0.001 });

    useEffect(() => {
        const foundPost = blogData.find(p => p.slug === slug);
        if (foundPost) {
            setPost(foundPost);
            window.scrollTo(0, 0);
        } else {
            navigate('/blog');
        }
    }, [slug, navigate]);

    if (!post) return null;

    return (
        <>
            <SEO title={`${post.title} | Blog`} description={post.excerpt} image={post.image} type="article" />

            {/* Reading Progress Indicator */}
            <motion.div className="fixed top-0 left-0 right-0 h-1 bg-primary z-[100] origin-left" style={{ scaleX }} />

            <article className="pt-20 pb-32">
                <div className="max-w-4xl mx-auto space-y-12">

                    <AnimationWrapper type="slideUp" duration={0.5} triggerOnce={true}>
                        <Link to="/blog" className="inline-flex items-center text-sm font-medium text-muted-foreground hover:text-foreground transition-colors mb-10 group">
                            <ArrowLeft className="mr-2 h-4 w-4 group-hover:-translate-x-1 transition-transform" /> Back to Articles
                        </Link>
                    </AnimationWrapper>

                    <header className="space-y-8">
                        <AnimationWrapper
                            type="fadeUp"
                            triggerOnce={true}
                            className="space-y-6"
                        >
                            <div className="flex flex-wrap items-center gap-4 text-xs font-bold tracking-widest text-muted-foreground uppercase">
                                <span className="px-3 py-1 bg-primary/10 text-primary border border-primary/20 rounded-lg">{post.category}</span>
                                <span className="flex items-center gap-1"><Calendar size={14} /> {post.date}</span>
                                <span className="flex items-center gap-1"><Clock size={14} /> {post.readTime}</span>
                            </div>
                            <TypographyH1 className="leading-tight">{post.title}</TypographyH1>
                        </AnimationWrapper>

                        <AnimationWrapper
                            type="zoomIn"
                            delay={0.2}
                            triggerOnce={true}
                            className="aspect-[21/9] w-full rounded-[2rem] overflow-hidden border bg-card shadow-sm"
                        >
                            <img src={post.image} alt={post.title} className="w-full h-full object-cover" />
                        </AnimationWrapper>
                    </header>

                    <div className="grid grid-cols-1 lg:grid-cols-[1fr_80px] gap-12 relative">
                        <AnimationWrapper
                            type="fadeUp"
                            triggerOnce={true}
                            className="prose prose-lg dark:prose-invert max-w-none 
                         prose-headings:font-bold prose-headings:tracking-tight
                         prose-a:text-primary prose-a:no-underline hover:prose-a:underline
                         prose-img:rounded-3xl prose-img:border prose-img:border-border/50
                         prose-pre:bg-muted prose-pre:border prose-pre:border-border/50 prose-pre:text-sm prose-pre:shadow-sm"
                        >
                            <p className="lead text-xl text-muted-foreground mb-10 font-medium">
                                {post.excerpt}
                            </p>

                            <p>When engineering high-performance user interfaces, managing state efficiently and optimizing the critical rendering path are paramount. This article explores deep architectural patterns and the latest APIs to unlock 60FPS experiences on any device.</p>

                            <h2>The Architecture of Speed</h2>
                            <p>Modern frontend frameworks provide fantastic abstractions, but pushing them to their limits requires mechanical sympathy. Understanding the Virtual DOM reconciliation process and execution contexts is the first step.</p>

                            <div className="bg-primary/5 border-l-4 border-primary p-6 rounded-r-2xl my-8">
                                <p className="m-0 font-medium text-foreground italic">"Premature optimization is the root of all evil, but overdue optimization is the death of user experience."</p>
                            </div>

                            <h3>1. Leveraging Concurrent Features</h3>
                            <p>By effectively splitting long-running tasks and utilizing selective hydration, we can dramatically reduce Time To Interactive (TTI) metrics.</p>

                            <pre className="p-6 rounded-2xl overflow-x-auto">
                                <code className="text-sm font-mono leading-loose">
                                    {`import { startTransition, useState } from 'react';

function SearchComponent() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);

  function handleChange(e) {
    // High priority state
    setQuery(e.target.value);
    
    // Low priority state wrapped in transition
    startTransition(() => {
      setResults(fetchExpensiveResults(e.target.value));
    });
  }

  // ...
}`}
                                </code>
                            </pre>

                            <h2>Conclusion</h2>
                            <p>Building performant applications isn't about using the newest tools—it's about understanding the underlying mechanics of the browser and employing thoughtful engineering practices at every layer of the stack.</p>
                        </AnimationWrapper>

                        {/* Floating Action Bar */}
                        <div className="hidden lg:block relative">
                            <div className="sticky top-32 flex flex-col items-center space-y-4">
                                <button
                                    onClick={() => setLikes(l => l + 1)}
                                    className="flex flex-col items-center justify-center w-14 h-14 rounded-full bg-card border shadow-sm hover:border-accent hover:text-accent transition-colors group"
                                >
                                    <Heart className="group-active:scale-75 transition-transform" />
                                    <span className="text-[10px] font-bold mt-1 text-muted-foreground group-hover:text-accent">{likes}</span>
                                </button>
                                <div className="w-8 border-t border-border/50 my-2" />
                                <button className="w-12 h-12 flex items-center justify-center rounded-full bg-card border shadow-sm text-muted-foreground hover:text-foreground hover:bg-muted transition-colors">
                                    <Share2 size={18} />
                                </button>
                                <button
                                    onClick={() => setIsSaved(!isSaved)}
                                    className="w-12 h-12 flex items-center justify-center rounded-full bg-card border shadow-sm text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
                                >
                                    {isSaved ? <BookmarkCheck size={18} className="text-secondary" /> : <Bookmark size={18} />}
                                </button>
                                <button onClick={() => window.print()} className="w-12 h-12 flex items-center justify-center rounded-full bg-card border shadow-sm text-muted-foreground hover:text-foreground hover:bg-muted transition-colors">
                                    <Printer size={18} />
                                </button>
                            </div>
                        </div>
                    </div>

                    {/* Mobile Actions */}
                    <div className="lg:hidden flex justify-center space-x-6 pt-10 border-t border-border/50">
                        <button onClick={() => setLikes(l => l + 1)} className="flex items-center space-x-2 text-muted-foreground hover:text-accent font-bold">
                            <Heart size={20} /> <span>{likes}</span>
                        </button>
                        <button className="text-muted-foreground hover:text-foreground"><Share2 size={20} /></button>
                        <button onClick={() => setIsSaved(!isSaved)} className="text-muted-foreground hover:text-foreground">
                            {isSaved ? <BookmarkCheck size={20} className="text-secondary" /> : <Bookmark size={20} />}
                        </button>
                    </div>

                </div>
            </article>
        </>
    );
};

