import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { motion, useScroll, useTransform } from 'framer-motion';
import SEO from '../components/SEO';
import { projectsData } from '../utils/data';
import { ArrowLeft, ExternalLink, Github, CheckCircle2, Award, Zap, Layout } from 'lucide-react';
import AnimationWrapper from '../components/shared/AnimationWrapper';

const TypographyH1 = ({ children, className = "" }) => (
    <h1 className={`scroll-m-20 text-4xl font-extrabold tracking-tight lg:text-5xl ${className}`}>{children}</h1>
);
const TypographyH2 = ({ children, className = "" }) => (
    <h2 className={`scroll-m-20 border-b border-border/50 pb-2 text-3xl font-semibold tracking-tight transition-colors ${className}`}>{children}</h2>
);
const TypographyH3 = ({ children, className = "" }) => (
    <h3 className={`scroll-m-20 text-2xl font-semibold tracking-tight ${className}`}>{children}</h3>
);
const TypographyP = ({ children, className = "" }) => (
    <p className={`leading-7 [&:not(:first-child)]:mt-6 text-muted-foreground ${className}`}>{children}</p>
);

const ProjectDetails = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const [project, setProject] = useState(null);

    const { scrollYProgress } = useScroll();
    const yParallax = useTransform(scrollYProgress, [0, 1], ["0%", "50%"]);

    useEffect(() => {
        const foundProject = projectsData.find(p => p.id === id);
        if (foundProject) {
            setProject(foundProject);
            window.scrollTo(0, 0);
        } else {
            navigate('/projects');
        }
    }, [id, navigate]);

    if (!project) return null;

    return (
        <>
            <SEO title={`${project.title} | Case Study`} description={project.description} image={project.image} />

            <article className="pt-20 pb-32">
                <div className="max-w-4xl mx-auto space-y-16">

                    <AnimationWrapper type="fadeRight" triggerOnce={true} duration={0.5}>
                        <Link to="/projects" className="inline-flex items-center text-sm font-medium text-muted-foreground hover:text-foreground transition-colors group">
                            <ArrowLeft className="mr-2 h-4 w-4 group-hover:-translate-x-1 transition-transform" /> Back to Projects
                        </Link>
                    </AnimationWrapper>

                    {/* Hero Section */}
                    <header className="space-y-8 text-center md:text-left relative">
                        <div className="absolute top-0 right-0 w-64 h-64 bg-primary/20 blur-[100px] rounded-full mix-blend-screen pointer-events-none -z-10" />
                        <AnimationWrapper
                            type="fadeUp"
                            triggerOnce={true}
                            className="space-y-6"
                        >
                            <div className="flex flex-wrap justify-center md:justify-start gap-2 mb-6">
                                {project.tags.map(tag => (
                                    <span key={tag} className="px-3 py-1 bg-primary/10 text-primary border border-primary/20 rounded-lg text-xs font-bold uppercase tracking-widest leading-none">
                                        {tag}
                                    </span>
                                ))}
                            </div>
                            <TypographyH1 className="leading-tight xl:leading-tight">
                                {project.title.split(' ').map((word, i, arr) => (
                                    i === arr.length - 1 ?
                                        <span key={i} className="text-transparent bg-clip-text bg-gradient-to-r from-primary to-accent"> {word}</span> :
                                        <span key={i}> {word}</span>
                                ))}
                            </TypographyH1>
                            <TypographyP className="text-xl md:text-2xl text-balance max-w-3xl">
                                {project.description}
                            </TypographyP>

                            <div className="flex flex-col sm:flex-row items-center gap-4 pt-6">
                                <a href={project.live} target="_blank" rel="noreferrer" className="inline-flex h-12 w-full sm:w-auto items-center justify-center rounded-md bg-primary px-8 text-sm font-medium text-primary-foreground shadow hover:bg-primary/90 transition-colors">
                                    <ExternalLink className="mr-2 h-4 w-4" /> Live Demo
                                </a>
                                <a href={project.github} target="_blank" rel="noreferrer" className="inline-flex h-12 w-full sm:w-auto items-center justify-center rounded-md border border-input bg-background/50 backdrop-blur px-8 text-sm font-medium shadow-sm hover:bg-accent hover:text-accent-foreground transition-colors">
                                    <Github className="mr-2 h-4 w-4" /> Source Code
                                </a>
                            </div>
                        </AnimationWrapper>
                    </header>

                    {/* Featured Image */}
                    <AnimationWrapper
                        type="zoomIn"
                        delay={0.2}
                        triggerOnce={true}
                        className="w-full aspect-video rounded-[3rem] overflow-hidden border bg-card shadow-xl relative"
                    >
                        <motion.img
                            style={{ y: yParallax }}
                            src={project.image}
                            alt={project.title}
                            className="w-full h-[150%] object-cover object-top -mt-[25%]"
                        />
                        <div className="absolute inset-x-0 bottom-0 h-1/2 bg-gradient-to-t from-background to-transparent" />
                    </AnimationWrapper>

                    {/* Problem & Solution Grid */}
                    <section className="grid md:grid-cols-2 gap-12 relative">
                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-full h-[1px] bg-border/50 hidden md:block" />
                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[1px] h-full bg-border/50 hidden md:block" />

                        <AnimationWrapper
                            type="fadeUp"
                            triggerOnce={true}
                            className="space-y-4 md:pr-12 md:pb-12"
                        >
                            <div className="inline-flex items-center space-x-2 text-primary font-bold tracking-widest uppercase mb-4 text-xs bg-primary/10 px-3 py-1 rounded-full">
                                <Layout size={14} /> The Problem
                            </div>
                            <TypographyH3 className="text-foreground">Scaling Legacy Architecture</TypographyH3>
                            <TypographyP>
                                The client's previous monolithic application was suffering from severe performance bottlenecks, 10+ second initial load times, and poor search engine visibility due to client-side only rendering approaches.
                            </TypographyP>
                        </AnimationWrapper>

                        <AnimationWrapper
                            type="fadeUp"
                            delay={0.2}
                            triggerOnce={true}
                            className="space-y-4 md:pl-12 md:pb-12"
                        >
                            <div className="inline-flex items-center space-x-2 text-secondary font-bold tracking-widest uppercase mb-4 text-xs bg-secondary/10 px-3 py-1 rounded-full">
                                <Zap size={14} /> The Solution
                            </div>
                            <TypographyH3 className="text-foreground">Modern Jamstack Evolution</TypographyH3>
                            <TypographyP>
                                Architected an entirely new frontend utilizing modern framework APIs, edge computing, static generation, and aggressive asset optimization to deliver instant page loads with 100/100 Lighthouse scores.
                            </TypographyP>
                        </AnimationWrapper>
                    </section>

                    {/* Stack & Metrics Section */}
                    <section className="bg-card border border-border/50 rounded-[3rem] p-8 md:p-16 shadow-sm">
                        <TypographyH2 className="border-none text-center mb-16">Technology Stack</TypographyH2>

                        <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                            {project.tags.map((tag, i) => (
                                <AnimationWrapper
                                    key={i}
                                    type="zoomIn"
                                    delay={i * 0.1}
                                    triggerOnce={true}
                                    className="flex flex-col items-center justify-center p-6 bg-muted rounded-2xl border hover:border-primary/50 transition-colors"
                                >
                                    <Code2 size={24} className="mb-3 text-primary" />
                                    <span className="font-bold text-sm tracking-tight text-foreground">{tag}</span>
                                </AnimationWrapper>
                            ))}
                        </div>

                        <div className="pt-20">
                            <TypographyH2 className="border-none text-center mb-12">Performance Impact</TypographyH2>
                            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-center">
                                {[
                                    { label: 'Performance', score: '99' },
                                    { label: 'Accessibility', score: '100' },
                                    { label: 'Best Practices', score: '100' },
                                    { label: 'SEO', score: '100' }
                                ].map((metric, i) => (
                                    <div key={i} className="relative aspect-square flex flex-col justify-center items-center group">
                                        <svg className="absolute inset-0 w-full h-full -rotate-90">
                                            <circle cx="50%" cy="50%" r="40%" className="stroke-muted fill-none stroke-[8%]" />
                                            <motion.circle
                                                cx="50%" cy="50%" r="40%"
                                                initial={{ strokeDasharray: '0 1000' }}
                                                whileInView={{ strokeDasharray: `${metric.score * 2.5} 1000` }}
                                                viewport={{ once: true }}
                                                transition={{ duration: 1.5, delay: 0.5, ease: "easeOut" }}
                                                className="stroke-emerald-500 fill-none stroke-[8%] stroke-linecap-round"
                                            />
                                        </svg>
                                        <span className="text-2xl md:text-3xl font-black text-foreground relative">{metric.score}</span>
                                        <span className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mt-1 relative">{metric.label}</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </section>

                    {/* Next Project CTA */}
                    <AnimationWrapper
                        type="fadeUp"
                        triggerOnce={true}
                        className="text-center py-24 border-t border-border/50"
                    >
                        <TypographyP className="text-primary font-bold uppercase tracking-widest text-sm mb-4">Up Next</TypographyP>
                        <TypographyH2 className="border-none text-4xl mb-10 text-foreground transition-colors hover:text-primary">
                            <Link to="/projects">Continue Exploring</Link>
                        </TypographyH2>
                    </AnimationWrapper>

                </div>
            </article>
        </>
    );
};

export default ProjectDetails;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import SEO from '../components/SEO';
import { projectsData } from '../utils/data';
import { Link } from 'react-router-dom';
import { ExternalLink, Github, Filter, MoveRight } from 'lucide-react';
import AnimationWrapper from '../components/shared/AnimationWrapper';

const TypographyH1 = ({ children, className = "" }) => (
    <h1 className={`scroll-m-20 text-4xl font-extrabold tracking-tight lg:text-5xl ${className}`}>{children}</h1>
);
const TypographyP = ({ children, className = "" }) => (
    <p className={`leading-7 [&:not(:first-child)]:mt-6 text-muted-foreground ${className}`}>{children}</p>
);

const Projects = () => {
    const [filter, setFilter] = useState('All');

    const techCategories = ['All', ...new Set(projectsData.flatMap(p => p.tags))];

    const filteredProjects = filter === 'All'
        ? projectsData
        : projectsData.filter(p => p.tags.includes(filter));

    return (
        <>
            <SEO title="Selected Works & Projects" description="A collection of frontend and full-stack projects showcasing modern architectures." />

            <div className="pt-20 space-y-24 min-h-screen">
                {/* Header */}
                <section className="text-center max-w-3xl mx-auto space-y-6">
                    <AnimationWrapper type="slideUp" triggerOnce={true}>
                        <div className="inline-flex items-center space-x-2 px-4 py-1.5 rounded-full bg-primary/10 text-primary border border-primary/20 mb-6">
                            <Filter size={16} />
                            <span className="text-xs font-bold uppercase tracking-widest leading-none">Portfolio Showcase</span>
                        </div>
                        <TypographyH1 className="mb-6">
                            Digital <span className="bg-gradient-to-r from-primary to-accent bg-clip-text text-transparent">Experiences</span>
                        </TypographyH1>
                        <TypographyP className="text-lg">
                            Explore a curated selection of projects where I've transformed complex problems into elegant, scalable, and fully responsive user interfaces.
                        </TypographyP>
                    </AnimationWrapper>
                </section>

                {/* Filters */}
                <section>
                    <AnimationWrapper
                        type="zoomIn"
                        delay={0.2}
                        className="flex flex-wrap justify-center gap-3 mb-16"
                    >
                        {techCategories.map(tech => (
                            <button
                                key={tech}
                                onClick={() => setFilter(tech)}
                                className={`px-5 py-2.5 rounded-full text-sm font-semibold transition-all duration-300 border ${filter === tech
                                    ? 'bg-primary text-primary-foreground border-primary shadow-sm shadow-primary/30 scale-105'
                                    : 'bg-card text-card-foreground border-border hover:border-primary/50 hover:bg-muted'
                                    }`}
                            >
                                {tech}
                            </button>
                        ))}
                    </AnimationWrapper>

                    {/* Project Grid */}
                    <motion.div layout className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                        <AnimatePresence mode="popLayout">
                            {filteredProjects.map((project, i) => (
                                <motion.div
                                    layout
                                    key={project.id}
                                    initial={{ opacity: 0, scale: 0.8 }}
                                    animate={{ opacity: 1, scale: 1 }}
                                    exit={{ opacity: 0, scale: 0.8 }}
                                    transition={{ duration: 0.4 }}
                                    className="group relative bg-card text-card-foreground rounded-[2.5rem] overflow-hidden border shadow-sm hover:shadow-2xl transition-all duration-500"
                                >
                                    <div className="aspect-[4/3] overflow-hidden relative">
                                        <img
                                            src={project.image}
                                            alt={project.title}
                                            className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110"
                                        />
                                        <div className="absolute inset-0 bg-background/20 group-hover:bg-transparent transition-colors duration-500" />
                                    </div>

                                    <div className="p-8">
                                        <div className="flex flex-wrap gap-2 mb-4">
                                            {project.tags.slice(0, 3).map(tag => (
                                                <span key={tag} className="inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold focus:outline-none focus:ring-2 focus:ring-ring bg-muted text-muted-foreground border-transparent">
                                                    {tag}
                                                </span>
                                            ))}
                                        </div>

                                        <h3 className="text-2xl font-bold tracking-tight mb-2 text-foreground group-hover:text-primary transition-colors">{project.title}</h3>
                                        <p className="text-muted-foreground text-sm line-clamp-3 mb-8">
                                            {project.description}
                                        </p>

                                        <div className="flex justify-between items-center border-t border-border/50 pt-6">
                                            <Link to={`/projects/${project.id}`} className="inline-flex items-center text-sm font-bold text-primary group-hover:underline">
                                                Case Study <MoveRight className="ml-2 h-4 w-4" />
                                            </Link>

                                            <div className="flex space-x-3 text-muted-foreground">
                                                <a href={project.github} target="_blank" rel="noreferrer" className="p-2 hover:bg-muted hover:text-foreground rounded-full transition-colors">
                                                    <Github size={18} />
                                                </a>
                                                <a href={project.live} target="_blank" rel="noreferrer" className="p-2 hover:bg-muted hover:text-primary rounded-full transition-colors">
                                                    <ExternalLink size={18} />
                                                </a>
                                            </div>
                                        </div>
                                    </div>
                                </motion.div>
                            ))}
                        </AnimatePresence>
                    </motion.div>

                    {filteredProjects.length === 0 && (
                        <AnimationWrapper type="zoomIn" className="text-center py-24 text-muted-foreground">
                            <p className="text-xl font-medium tracking-tight">No projects found for the selected technology.</p>
                            <button onClick={() => setFilter('All')} className="mt-4 text-primary font-bold hover:underline">Clear Filters</button>
                        </AnimationWrapper>
                    )}
                </section>
            </div>
        </>
    );
};

export default Projects;

