);
const TypographyH2 = ({ children, className = "" }) => (
    <h2 className={`scroll-m-20 border-b border-border/50 pb-2 text-3xl font-semibold tracking-tight transition-colors ${className}`}>{children}</h2>
);
const TypographyP = ({ children, className = "" }) => (
    <p className={`leading-7 [&:not(:first-child)]:mt-6 text-muted-foreground ${className}`}>{children}</p>
);

const Services = () => {
    const { scrollYProgress } = useScroll();
    const yParallax = useTransform(scrollYProgress, [0, 1], ["0%", "-20%"]);

    return (
        <>
            <SEO title="Services & Capabilities" description="Professional web development, UI/UX design, and technical consulting services." />

            <div className="pt-20 space-y-32 relative">
                {/* Background gradient animation */}
                <motion.div
                    style={{ y: yParallax }}
                    className="absolute inset-0 z-[-1] pointer-events-none"
                >
                    <div className="absolute top-[10%] left-[20%] w-[30vw] h-[30vw] rounded-full bg-primary/20 blur-[150px] mix-blend-screen" />
                    <div className="absolute top-[40%] right-[10%] w-[40vw] h-[40vw] rounded-full bg-accent/20 blur-[150px] mix-blend-screen" />
                </motion.div>

                {/* Hero Section */}
                <section className="text-center max-w-4xl mx-auto space-y-6">
                    <AnimationWrapper
                        type="zoomIn"
                        triggerOnce={true}
                    >
                        <div className="inline-flex items-center space-x-2 px-4 py-1.5 rounded-full bg-secondary/10 text-secondary border border-secondary/20 mb-6">
                            <Zap size={16} />
                            <span className="text-xs font-bold uppercase tracking-widest leading-none">Engineering Value</span>
                        </div>
                        <TypographyH1 className="mb-6">
                            My <span className="bg-gradient-to-r from-primary via-secondary to-accent bg-clip-text text-transparent">Capabilities</span>
                        </TypographyH1>
                        <TypographyP className="text-lg">
                            From concept to deployment, I offer end-to-end technical solutions tailored to modern web standards, performance metrics, and user-centric design principles.
                        </TypographyP>
                    </AnimationWrapper>
                </section>

                {/* Services Layout */}
                <section className="space-y-16">
                    {servicesData.map((service, index) => {
                        const isEven = index % 2 === 0;
                        return (
                            <AnimationWrapper
                                key={service.id}
                                type="fadeUp"
                                triggerOnce={true}
                                className={`grid grid-cols-1 lg:grid-cols-2 gap-12 lg:gap-24 items-center ${isEven ? '' : 'lg:flex-row-reverse'}`}
                            >
                                {/* Content */}
                                <div className={`space-y-6 ${!isEven && 'lg:order-2'}`}>
                                    <div className={`p-4 rounded-2xl w-max ${index === 0 ? 'bg-primary/10 text-primary' :
                                        index === 1 ? 'bg-accent/10 text-accent' :
                                            'bg-secondary/10 text-secondary'
                                        }`}>
                                        {index === 0 ? <Code2 size={40} /> : index === 1 ? <Palette size={40} /> : <Rocket size={40} />}
                                    </div>
                                    <TypographyH2 className="border-none">{service.title}</TypographyH2>
                                    <TypographyP>{service.description}</TypographyP>
                                    <ul className="space-y-4 pt-4">
                                        {service.features.map((feature, i) => (
                                            <li key={i} className="flex items-center space-x-3 text-foreground font-medium">
                                                <ArrowRight size={18} className="text-primary" />
                                                <span>{feature}</span>
                                            </li>
                                        ))}
                                    </ul>
                                </div>

                                {/* Visual Concept */}
                                <div className={`relative ${!isEven && 'lg:order-1'}`}>
                                    <div className="absolute inset-0 bg-gradient-to-tr from-primary/30 to-background blur-[80px] rounded-full mix-blend-screen" />
                                    <motion.div
                                        whileHover={{ scale: 1.05, rotateY: 5 }}
                                        className="relative aspect-square glass-card rounded-[3rem] p-8 border border-border shadow-2xl flex flex-col justify-center items-center bg-card"
                                    >
                                        <div className="grid grid-cols-2 gap-4 w-full h-full p-4">
                                            <div className="bg-muted rounded-2xl animate-pulse delay-100" />
                                            <div className="bg-primary/20 rounded-full animate-bounce-slow" />
                                            <div className="bg-secondary/20 rounded-full animate-bounce-slow delay-500" />
                                            <div className="bg-accent/20 rounded-2xl animate-pulse delay-300" />
                                        </div>
                                    </motion.div>
                                </div>
                            </AnimationWrapper>
                        )
                    })}
                </section>

                {/* Process Flow */}
                <section className="py-24 border-t border-border/50">
                    <div className="text-center mb-16">
                        <TypographyH2 className="border-none">Delivery Workflow</TypographyH2>
                        <TypographyP className="max-w-xl mx-auto">A transparent, iterative process ensuring alignment, speed, and uncompromising quality.</TypographyP>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                        {[
                            { title: 'Discovery', desc: 'Requirements gathering and architecture planning.' },
                            { title: 'Design', desc: 'Wireframing UI/UX and finalizing the design system.' },
                            { title: 'Development', desc: 'Agile sprints with regular milestone demos.' },
                            { title: 'Deployment', desc: 'Performance audits, SEO checks, and launch.' }
                        ].map((step, i) => (
                            <AnimationWrapper
                                key={i}
                                type="fadeUp"
                                delay={i * 0.1}
                                triggerOnce={true}
                                className="relative p-8 bg-card text-card-foreground border shadow-sm rounded-3xl"
                            >
                                <div className="text-6xl font-black text-muted/30 absolute top-4 right-6 pointer-events-none">0{i + 1}</div>
                                <h4 className="text-xl font-bold mb-4 relative z-10">{step.title}</h4>
                                <p className="text-muted-foreground text-sm relative z-10">{step.desc}</p>
                                {i < 3 && <MoveRight className="hidden md:block absolute -right-6 top-1/2 -translate-y-1/2 text-muted-foreground" size={24} />}
                            </AnimationWrapper>
                        ))}
                    </div>
                </section>

                {/* CTA */}
                <section className="text-center pb-24">
                    <Link to="/contact" className="inline-flex h-14 items-center justify-center rounded-full bg-primary px-10 text-base font-bold text-primary-foreground shadow hover:bg-primary/90 hover:scale-105 transition-all">
                        Ready to Collaborate <ArrowRight className="ml-2 h-5 w-5" />
                    </Link>
                </section>
            </div>
        </>
    );
};

export default Services;

import React from 'react';
import SEO from '../components/SEO';
import { Layout, Server, Database, Cloud, Code, Terminal, Layers, Monitor, Cpu, Search, Sparkles } from 'lucide-react';
import { motion, useScroll, useTransform } from 'framer-motion';
import AnimationWrapper from '../components/shared/AnimationWrapper';

const TypographyH1 = ({ children, className = "" }) => (
    <h1 className={`scroll-m-20 text-4xl font-extrabold tracking-tight lg:text-5xl ${className}`}>{children}</h1>
);
const TypographyH2 = ({ children, className = "" }) => (
    <h2 className={`scroll-m-20 border-b border-border/50 pb-2 text-3xl font-semibold tracking-tight transition-colors ${className}`}>{children}</h2>
);
const TypographyP = ({ children, className = "" }) => (
    <p className={`leading-7 [&:not(:first-child)]:mt-6 text-muted-foreground ${className}`}>{children}</p>
);

const Skills = () => {
    const { scrollYProgress } = useScroll();
    const scaleTitle = useTransform(scrollYProgress, [0, 0.2], [1, 1.1]);

    const frontend = [
        { name: 'React / Next.js', percentage: 95, color: 'bg-cyan-500' },
        { name: 'TypeScript', percentage: 90, color: 'bg-blue-600' },
        { name: 'Tailwind CSS / Shadcn', percentage: 98, color: 'bg-emerald-400' },
        { name: 'Framer Motion / GSAP', percentage: 85, color: 'bg-purple-500' },
        { name: 'Vue.js / Nuxt', percentage: 80, color: 'bg-emerald-500' }
    ];

    const backend = [
        { name: 'Node.js / Express', percentage: 85, color: 'bg-green-600' },
        { name: 'PostgreSQL / MongoDB', percentage: 80, color: 'bg-sky-600' },
        { name: 'GraphQL / REST APIs', percentage: 90, color: 'bg-pink-600' },
        { name: 'Python / Django', percentage: 70, color: 'bg-blue-500' }
    ];

    return (
        <>
            <SEO title="Skills & Technologies | Portfolio" description="A comprehensive breakdown of my technical stack and proficiency." />

            <div className="pt-20 space-y-32">
                {/* Header Section */}
                <section className="text-center relative">
                    <motion.div style={{ scale: scaleTitle }} className="inline-block relative z-10">
                        <TypographyH1 className="mb-4">
                            Technical <br />
                            <span className="bg-gradient-to-r from-primary via-secondary to-accent bg-clip-text text-transparent">Arsenal</span>
                        </TypographyH1>
                        <TypographyP className="max-w-xl mx-auto">
                            I leverage a diverse ecosystem of modern tools, frameworks, and languages to build robust, scalable, and visually stunning digital experiences.
                        </TypographyP>
                    </motion.div>
                    {/* Abstract background shapes */}
                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-96 h-96 bg-primary/20 blur-[120px] rounded-full mix-blend-screen pointer-events-none" />
                </section>

                {/* Skill Bars Section */}
                <section className="grid grid-cols-1 lg:grid-cols-2 gap-16">
                    {/* Frontend */}
                    <AnimationWrapper
                        type="fadeRight"
                        triggerOnce={true}
                        className="space-y-8 p-10 bg-card border rounded-[2rem] shadow-sm relative overflow-hidden group"
                    >
                        <div className="absolute top-0 right-0 p-8 opacity-5 group-hover:opacity-10 transition-opacity"><Layout size={100} /></div>
                        <TypographyH2 className="border-none flex items-center gap-3">
                            <Code className="text-primary" /> Frontend Development
                        </TypographyH2>
                        <div className="space-y-6 relative z-10">
                            {frontend.map((skill, index) => (
                                <div key={index}>
                                    <div className="flex justify-between mb-2">
                                        <span className="font-bold text-sm tracking-tight text-foreground">{skill.name}</span>
                                        <span className="text-xs font-mono text-muted-foreground">{skill.percentage}%</span>
                                    </div>
                                    <div className="h-2 w-full bg-muted rounded-full overflow-hidden border border-border/50">
                                        <motion.div
                                            className={`h-full ${skill.color} brightness-110 shadow-lg`}
                                            initial={{ width: 0 }}
                                            whileInView={{ width: `${skill.percentage}%` }}
                                            viewport={{ once: true }}
                                            transition={{ duration: 1, delay: 0.2 + (index * 0.1), ease: "easeOut" }}
                                        />
                                    </div>
                                </div>
                            ))}
                        </div>
                    </AnimationWrapper>

                    {/* Backend */}
                    <AnimationWrapper
                        type="fadeLeft"
                        triggerOnce={true}
                        className="space-y-8 p-10 bg-card border rounded-[2rem] shadow-sm relative overflow-hidden group"
                    >
                        <div className="absolute top-0 right-0 p-8 opacity-5 group-hover:opacity-10 transition-opacity"><Server size={100} /></div>
                        <TypographyH2 className="border-none flex items-center gap-3">
                            <Database className="text-secondary" /> Backend Development
                        </TypographyH2>
                        <div className="space-y-6 relative z-10">
                            {backend.map((skill, index) => (
                                <div key={index}>
                                    <div className="flex justify-between mb-2">
                                        <span className="font-bold text-sm tracking-tight text-foreground">{skill.name}</span>
                                        <span className="text-xs font-mono text-muted-foreground">{skill.percentage}%</span>
                                    </div>
                                    <div className="h-2 w-full bg-muted rounded-full overflow-hidden border border-border/50">
                                        <motion.div
                                            className={`h-full ${skill.color} brightness-110 shadow-lg`}
                                            initial={{ width: 0 }}
                                            whileInView={{ width: `${skill.percentage}%` }}
                                            viewport={{ once: true }}
                                            transition={{ duration: 1, delay: 0.2 + (index * 0.1), ease: "easeOut" }}
                                        />
                                    </div>
                                </div>
                            ))}
                        </div>
                    </AnimationWrapper>
                </section>

                {/* Tools Grid */}
                <section>
                    <div className="text-center mb-16">
                        <TypographyH2 className="border-none">Tools & Methodologies</TypographyH2>
                        <TypographyP className="max-w-xl mx-auto">Beyond syntax, I focus on the entire development lifecycle, utilizing cutting-edge tools to ensure delivery quality.</TypographyP>
                    </div>

                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
                        {[
                            { icon: <Cloud size={32} />, title: 'Cloud Infrastructure', desc: 'AWS, Vercel, Netlify' },
                            { icon: <Terminal size={32} />, title: 'DevOps & CI/CD', desc: 'Docker, GitHub Actions' },
                            { icon: <Layers size={32} />, title: 'Design Architecture', desc: 'Atomic Design, Tailwind CSS' },
                            { icon: <Monitor size={32} />, title: 'UI/UX Design', desc: 'Figma, Adobe XD' },
                            { icon: <Search size={32} />, title: 'SEO Strategy', desc: 'Lighthouse, Core Web Vitals' },
                            { icon: <Cpu size={32} />, title: 'State Management', desc: 'Redux, Zustand, Context' },
                            { icon: <Sparkles size={32} />, title: 'Animations', desc: 'Framer Motion, GSAP' },
                            { icon: <Database size={32} />, title: 'Version Control', desc: 'Git, GitHub, GitLab' },
                        ].map((tool, i) => (
                            <AnimationWrapper
                                key={i}
                                type="zoomIn"
                                delay={i * 0.05}
                                triggerOnce={true}
                                whileHover={{ y: -5 }}
                                className="p-6 bg-card border rounded-2xl flex flex-col items-center text-center shadow-sm hover:shadow-lg transition-all group"
                            >
                                <div className="p-4 bg-muted text-primary rounded-xl mb-4 group-hover:scale-110 group-hover:bg-primary/10 transition-transform">
                                    {tool.icon}
                                </div>
                                <h3 className="font-bold text-foreground mb-1 tracking-tight">{tool.title}</h3>
                                <p className="text-xs text-muted-foreground">{tool.desc}</p>
                            </AnimationWrapper>
                        ))}
                    </div>
                </section>
            </div>
        </>
    );
};

export default Skills;

import React from 'react';
import SEO from '../components/SEO';
import { testimonialsData } from '../utils/data';
import { Quote, MessageSquare, Star, ArrowRight, Zap, Award } from 'lucide-react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import AnimationWrapper from '../components/shared/AnimationWrapper';

const TypographyH1 = ({ children, className = "" }) => (
    <h1 className={`scroll-m-20 text-4xl font-extrabold tracking-tight lg:text-5xl ${className}`}>{children}</h1>
);
const TypographyP = ({ children, className = "" }) => (
    <p className={`leading-7 [&:not(:first-child)]:mt-6 text-muted-foreground ${className}`}>{children}</p>
);

const Testimonials = () => {
    return (
        <>
            <SEO title="Testimonials & Reviews" description="Feedback from innovative companies and leaders I've had the pleasure of working with." />

            <div className="pt-20 space-y-32">
                {/* Header Section */}
                <section className="text-center relative max-w-4xl mx-auto space-y-8">
                    <AnimationWrapper
                        type="fadeUp"
                        triggerOnce={true}
                    >
                        <div className="inline-flex items-center space-x-2 px-4 py-1.5 rounded-full bg-accent/10 border border-accent/20 text-accent mb-6">
                            <MessageSquare size={16} />
                            <span className="text-xs font-bold uppercase tracking-widest leading-none">Client Feedback</span>
                        </div>

                        <TypographyH1>
                            Stories of <br />
                            <span className="bg-gradient-to-r from-primary via-secondary to-accent bg-clip-text text-transparent">Digital Innovation</span>
                        </TypographyH1>

                        <TypographyP className="text-lg md:text-xl">
                            Trust is built through results. Here's a collection of feedback from some of the most innovative companies and leaders I've collaborated with.
                        </TypographyP>
                    </AnimationWrapper>

                    <AnimationWrapper
                        type="zoomIn"
                        delay={0.3}
                        triggerOnce={true}
                        className="grid grid-cols-1 md:grid-cols-3 gap-8 pt-10"
                    >
                        {[
                            { label: '5-Star Reviews', value: '45+', icon: <Star className="text-amber-400" /> },
                            { label: 'Repeat Clients', value: '92%', icon: <Zap className="text-primary" /> },
                            { label: 'Industry Awards', value: '12+', icon: <Award className="text-secondary" /> }
                        ].map((stat, i) => (
                            <div key={i} className="p-8 bg-card border rounded-[2rem] shadow-sm flex flex-col items-center">
                                <div className="p-4 bg-muted rounded-2xl mb-4">{stat.icon}</div>
                                <h3 className="text-3xl font-black text-foreground mb-1 tracking-tighter">{stat.value}</h3>
                                <p className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">{stat.label}</p>
                            </div>
                        ))}
                    </AnimationWrapper>
                </section>

                {/* Testimonials Grid */}
                <section className="grid grid-cols-1 md:grid-cols-2 gap-12 lg:gap-16">
                    {testimonialsData.map((t, i) => (
                        <AnimationWrapper
                            key={i}
                            type="fadeUp"
                            delay={i * 0.1}
                            triggerOnce={true}
                            className="relative p-10 bg-card border border-border/50 rounded-[3rem] shadow-sm flex flex-col justify-between group overflow-hidden"
                        >
                            <Quote className="absolute top-8 right-8 text-primary/10 w-24 h-24 rotate-12 group-hover:rotate-0 transition-transform duration-500" />
                            <div className="relative z-10">
                                <div className="flex text-amber-500 mb-6">
                                    {[...Array(5)].map((_, i) => <Star key={i} fill="currentColor" size={20} />)}
                                </div>
                                <p className="text-xl md:text-2xl font-medium tracking-tight text-foreground leading-relaxed mb-10 italic">"{t.text}"</p>
                                <div className="flex items-center space-x-4">
                                    <div className="w-16 h-16 rounded-full overflow-hidden ring-2 ring-primary/20">
                                        <img src={t.avatar} alt={t.name} className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-700" />
                                    </div>
                                    <div>
                                        <h4 className="font-bold text-foreground text-lg tracking-tight">{t.name}</h4>
                                        <p className="text-sm font-semibold text-primary uppercase tracking-wider">{t.position}</p>
                                    </div>
                                </div>
                            </div>
                        </AnimationWrapper>
                    ))}
                </section>

                {/* Future CTA */}
                <section className="py-24 text-center">
                    <AnimationWrapper
                        type="zoomIn"
                        triggerOnce={true}
                        className="glass-card max-w-3xl mx-auto rounded-[3rem] p-16 border shadow-2xl relative overflow-hidden bg-card"
                    >
                        <div className="absolute inset-0 bg-gradient-to-tr from-primary/10 via-background to-secondary/10" />
                        <TypographyH1 className="relative z-10 mb-8 border-none">Ready to start?</TypographyH1>
                        <Link to="/contact" className="relative z-10 inline-flex items-center justify-center h-14 px-10 rounded-full font-bold bg-primary text-primary-foreground shadow hover:scale-105 transition-transform">
                            Let's Build Something Amazing <ArrowRight className="ml-2 h-5 w-5" />
                        </Link>
                    </AnimationWrapper>
                </section>
            </div>
        </>
    );
};

export default Testimonials;

